// GENERATED by worker/scripts/build-policy-content.mjs from policies/privacy.html and policies/terms.html; do not edit.
// The main text is the tracked policy text unchanged; the shell is the Worker's (.65). `npm run check:policies` fails when stale.
const PRIVACY = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Olympus Verify — Privacy Policy</title>\n<meta name=\"color-scheme\" content=\"dark\">\n<link rel=\"stylesheet\" href=\"/static/policies.css\">\n</head>\n<body class=\"olympus-policy\">\n<a class=\"skip-link\" href=\"#policy-content\">Skip to policy</a>\n<header class=\"policy-header\">\n<a class=\"brand\" href=\"/\">Olympus</a>\n<nav aria-label=\"Policies\"><a href=\"/privacy\" aria-current=\"page\">Privacy Policy</a><a href=\"/terms\">Terms of Service</a></nav>\n</header>\n<main id=\"policy-content\" tabindex=\"-1\">\n<h1>Privacy Policy</h1>\n<p class=\"meta\">Olympus Verify and the Olympus guild site · last updated 3 October 2026</p>\n\n<p>Olympus Verify is a private bot run by the volunteer staff of the World of Warcraft guild &ldquo;Olympus&rdquo;. It\nserves the Olympus channels in Asmongold's Discord server, and it is not offered to the public or installed anywhere\nelse. It exists to prove that a Discord account and an in-game character belong to the\nsame person, so guild channels can be opened to guild members without an officer checking every name by hand.</p>\n\n<h2>What it stores</h2>\n<p>Only what that check needs: your Discord user ID and display name; the characters you verify, with where each stands (code confirmed, invite queued, sent or refused,\njoined or left) and when; the in-game guild roster as the officers' addon exports it &mdash; each member's character name,\nrank, level, class, public and officer notes and last-online time, and the date the name first appeared &mdash; kept as\ndated snapshots (where the officers have switched on the guild note, the public note the bot has the addon write when you\njoin is <code>D:</code> followed by your Discord user ID, and every later export carries it), each also recording when that\nexact roster first arrived, whether all of it was stored, and whether it passed the bot's size checks (not much smaller\nthan the last export that passed them and not below a set minimum, or an officer vouched for it); a rank is the one the\nguild gives in game and can reflect a staff decision (for example a probation rank, where the guild uses one), and the\nsnapshots keep it as it was exported; and a dated log of actions\ntaken (role granted, role removed, application approved or denied, a character unbound, a ban), each entry naming who\nacted, whom or what it concerned and the fixed details that action records (a denial or ban reason as the officer typed\nit; for an unbind, the account the character was bound to before), so officers can answer &ldquo;why did this\nhappen&rdquo;. It also keeps your Discord username and display name, as Discord reports them, for the characters you have\nlinked.</p>\n\n<h2>The guild site</h2>\n<p>The Olympus registration site (olympus.roachcouncil.com; its old address, guild.roachcouncil.com, forwards to it)\nsigns you in with Discord and checks one thing about your\nservers: whether you are a member of Asmongold's Discord server. For that it asks Discord for your identity and your\nmembership in that one server. It stores your Discord user ID, username, display name, nickname and avatar in that\nserver, when your Discord account was created and when you joined that server; what you enter &mdash; your application\n(your first choice and up to two backup roles, your answers, and the professions you plan to take if you name any),\nthe times of the week you usually play (kept as hours of the week in UTC, with your time zone), your votes on the\nvoting board, the people you write in for a role and why, the friends you list, and the character names you reserved\n&mdash; and when you signed in. It never receives your Discord password, your email address, your other servers or\nyour messages, and it keeps no Discord access token after you are signed in. The site's top bar shows you your own\nDiscord picture: your browser loads it from Discord's picture server (cdn.discordapp.com), so Discord sees that request;\nthe site shows that picture to no one else.</p>\n<p><strong>The voting board.</strong> Leadership roles are voted on, except those the guild's leadership chooses\nwithout a public vote (the site marks them); an application for only such roles is not shown on the board. If you\napply for a role that is voted on and tick the box that shows your application on the voting board, every member\nsigned in to the site can read it there, under each role you chose that is voted on then or later: your Discord display\nname and, as its picture, the game's own class icon for the class you gave (the board shows the game's icons, never your\nDiscord picture; the avatar reference Discord gave at sign-in stays stored with your account record, as said above),\nyour class, role and where you play from, which roles you chose (first choice or backup), how many NA and\nEU raid evenings a week you can make, and your answers to the four questions about your experience, why Olympus,\nleading people, and the loot argument. Your main character, professions, logs, references, voice chat, hours, weekly\nschedule and the last free-text box are never shown there. An application leaves the board when you withdraw it or\nonce the leadership has decided it. Votes on the board and people written in for a role are counted and seen only by\nthe site's administrators; nobody else, including the applicants and the people written in, sees how anyone voted or\nany counts. Someone you write in is told the role the next time they sign in, never by whom.</p>\n<p><strong>Appointed roles.</strong> The site's administrators may fill a role by appointment instead of the board and\ntype the holder's name (up to 40 characters, tied to no Discord account), and they type a name only after that person\nagreed. An appointed name is public: anyone, signed in or not, sees it on the Roles page and wherever the site names the\nrole, the site's public settings carry it, and search engines and web archives on the open web may copy it; removing it\nhere cannot recall their copies. An appointment gives no powers in the bot, the site or Discord, and an administrator\nclears it after the beta has closed. The dated log records which roles were appointed and how many names were saved,\nnever the names (and whether the site-wide notice was set, never its text). Build .115 rewrites the entries written\nbefore it the same way, once, when it first starts; if that fails, the failure is logged and the rewrite is tried again\nat a later start, and after installing it the owner checks that the rewrite is recorded as done and that no such entry\nstill holds a name or a notice's text.</p>\n<p><strong>A full guild.</strong> While Olympus I is full (the officers' latest roster export counts the member limit,\nwhen that export is complete, passed the size checks and is less than two days old; or an invite was just refused for\nlack of space), <code>/verify-status</code> says so, with the hour of that export or refusal, to an account waiting on an\ninvite, and the site's Home and Apply pages say so to an account waiting in the invite queue (with its place) or without\na confirmed character (with that hour). Your own characters' places in the invite queue are shown to you, and only you.\nNo other member sees your place. Officers see the invite queue itself (the character names, the accounts and their\norder) in their staff commands, and the bot's private staff channels record each confirmation (the character and the\naccount, never a code) and, while the guild is full, how many are waiting.</p>\n\n<h2>The community pages</h2>\n<p>The site has community pages that the guild's staff switch on one at a time; a page that is off shows nothing and\ntakes no new entries or actions, while what it already holds stays in your copy, keeps the lifetime stated below, is\ncleaned up on the same schedule, can still be erased on request, and stays in the dated log as before. Each stores only\nwhat you enter there or\nwhat the officers record, under your Discord user ID. Nothing on these pages changes your Discord roles, your guild\nmembership or your access by itself: the officers decide those, and this software keeps the records.</p>\n<p><strong>Member directory and crafting offers.</strong> You may list, for other guild members, a main character, a\nraid role, up to four professions with a skill level, up to ten alts you claim, and up to fifty crafting offers. They are\nshown to members signed in to the site whose own character the officers' roster export confirms, only while you keep them\nlisted and remain such a member yourself; other members see you by your display name and a random reference, never your\nDiscord user ID. A character name you enter is a label until it matches the officers' record of your characters; a name\nbound to another account is refused. Officers may confirm or reject a claimed alt. A profile whose owner is no longer a\nconfirmed member stops being shown at once and is deleted, with everything under it, by the scheduled cleanup from\nthirty days later.</p>\n<p><strong>The leadership directory.</strong> The site's administrators may list, for each Olympus guild (Olympus I to\nOlympus X), its Guild Master and officers by the names they type, and they list a name only after that person agreed.\nConfirmed members can read it. A listing is a record only: it gives no powers in the bot, the site or Discord. An\nadministrator clears it after the beta has closed and changes it when the leadership changes. Anyone listed there or\nappointed to a role (see the guild site, above) can ask any Olympus officer, or use the private request form, to have\nthe name removed or corrected, and an administrator does it at once: the name is cleared, or replaced by &ldquo;Name\nwithheld&rdquo;, which keeps an appointed role appointed.</p>\n<p><strong>News.</strong> When the site's administrators switch it on (it is off until they do), confirmed members can\nread a News page. It shows notices the administrators post for the whole guild, and figures the site works out by\nitself: whether Olympus I has room, with the hour of the roster export or refused invite that says so; how many characters\njoined and left the guild in the last day and the last seven days, compared between complete roster exports that passed\nthe size checks; how many applications were first saved and how many decisions were saved in the same periods, where a\ncount from one to four is shown only as &ldquo;fewer than 5&rdquo;; when the leadership directory last changed, never its\nnames; the beta's dates; and the site's release notes. The figures are counts and times, never a name or anyone's place\nin line, and are worked out at most every three hours, only while the page is on. The page also lists the next events\nby their start times and the titles their organizers gave them; a title is free text, shown exactly as the calendar\nalready shows it to confirmed members (see Calendar and attendance). A notice is different: it is free text an\nadministrator writes for the whole guild, shown as plain text,\nand the site does not check what it says. The administrators name a member in a notice only with that member's\nagreement, and anyone a notice names can ask any Olympus officer, or use the private request form, to have it changed or\ndeleted, and an administrator does it at once. A notice is shown for the period the administrator chose, from 1 to 90\ndays after it was first posted (judged by the database's own clock in every read), and then deleted by the scheduled\ncleanup; an administrator may change or delete it sooner. Members see when a notice was posted and last changed, not who\nwrote it: the administrator who posted it and the one who last changed it are recorded for the staff only. A notice that\nwas deleted or ran out leaves behind only its id, who posted it and when, until 120 days after it was posted, and a page\ncan post a new notice only within 30 days of being opened, so a page opened earlier cannot post it again. The dated log\nrecords that a notice was posted, changed or deleted and how many are shown, never a title or a text.</p>\n<p><strong>Calendar and attendance.</strong> Organizers (the site's administrators and the members named as organizers)\ncreate events: a title, details, start, duration, capacity and the roles wanted. You answer yes, tentative or no with a\ncharacter and a raid role, and you can give or change that answer only before the event starts, while the calendar is on\nand you are a confirmed member; your answer, display name and character are visible to confirmed members looking at the\nevent, and it holds a place only while you remain one. After an event started an organizer may record\nattendance (present, possibly late or having left early; absent; excused; or unknown). Attendance never feeds roles,\neligibility or any penalty. An event, its answers, attendance and history are deleted by the scheduled cleanup from\nthirty days after it ends (a cancellation brings that forward).</p>\n<p><strong>Trial reviews.</strong> Officers may record a trial about your account: when it began, when its review is\ndue, whether it was extended, and how it concluded (passed, or ended with a fixed reason). You can read your own trial's\nstatus and dates on the site, never the sponsor or the officers involved. A trial is kept thirty days after it concluded,\nor after its review was due if it never did; from that moment no page shows it and no new copy contains it, and the row\nis deleted in the scheduled cleanup (bounded batches, so it may take more than one run).</p>\n<p><strong>Restriction cases, the watch-list and the return review.</strong> Officers may record a case about a Discord\naccount &mdash; a ban, a removal for conduct, or a removal for unpaid guild dues &mdash; with its dates, review and appeal\ndecisions, and may record that the same account signed in again after the case was set. A case may carry a watch-list:\nthe names and in-game identifiers of that account's characters, copied from the officers' own record, so the officers can\nsee when another account later holds one of them. Watch-list rows are kept for at most twelve months per member (one\nperiod, which an officer may renew with a fixed reason), never longer than their case. These are staff records and review\nevidence only: nothing here bans, removes or recognizes anyone by itself. A removal case ends at its expiry (at most two\nyears), a ban case when an officer resolves it; a resolved case is kept thirty days. Past those moments no page shows the\ncase and no new copy contains it.</p>\n<p><strong>Departure review items.</strong> When a character bound to your account leaves or is removed from the\nin-game guild, a review item (the character, whether it left or was removed, the date) exists for thirty days so an\nofficer can acknowledge it or open a case from it. Nothing is decided by the item itself.</p>\n<p><strong>Guild dues (the contribution ledger).</strong> When the officers switch it on, the site keeps a ledger of the\nweekly guild dues in in-game copper: your weeks (eligible or exempt, due, paid, acknowledged), the payments the officers\nrecord (amount, date and source; the payer name as written in the game is for officers only), and your acknowledgements\nof a notice. The site shows you a mail reference to put in the subject of the in-game mail so an officer can match it to\nyou; it is a matching aid, not proof of payment &mdash; the officer records the payment. Nothing is sent to you or taken\nfrom you by this software; an officer may record that you were removed in game for unpaid dues, which is a record, not an\naction. Ledger records are kept for the period the officers set when they switch it on (between one day and ten years,\nfixed when each record is written). Past its period a week is answered to no one; past its period a recorded payment's\nprivate details (its source identifier, the payer name as written, who recorded it) become unavailable at once and its\nunused remainder can never pay a later week, with one narrow exception kept on purpose: while a payment already paid a\nweek that is itself still within its period, the minimum the accounting needs stays with that week: the payment's kind\n(an officer's entry, a mail, a bank log), the amount it paid that week and the part already retired, its date and status,\nand which week it paid; nothing more, so the week's paid state is never falsified, and it goes when the week goes.</p>\n\n<p>It does not store your Blizzard password or your Discord password &mdash; it never sees either. It does not read or\nstore your Discord messages or DMs, your email address, your IP address, your real-money payment details (it has no\npayments), or anything about your activity outside this one guild. The in-game copper the guild dues ledger records, when\nthe officers switch it on, is described under the community pages. In the game, the officers' addon reads the\nverification codes whispered or mailed to an officer's character, the game's own guild join and leave messages, the guild\nroster and the result of each invite it sends. A companion program on that officer's computer reads the game client's chat\nlog file (which holds whatever chat that client logs) and the addon's saved data, and forwards to the bot only what it\nextracts from them: the code, the character and guild names, the invite outcomes, the roster export, whether that officer\nis in the world, and a timing measurement of the log file itself. By its code nothing else is sent, and the chat log stays\non that officer's computer; this describes the software as written, not a guarantee about the game client.</p>\n\n<p><strong>If you are banned from verifying</strong>, the bot keeps your Discord user ID and the reason; the\ncharacters bound to that account stay bound to it.</p>\n<p><strong>Battle.net.</strong> Battle.net sign-in is switched off: the bot offers no Battle.net link and receives\nnothing from Blizzard. A BattleTag and Battle.net account ID stored by an earlier link are deleted automatically within\n29 days of that link. If you linked before, Discord keeps its own linked-role record for this bot under your Discord\naccount (a &ldquo;Battle.net linked&rdquo; mark, and for links made before early October 2026 your BattleTag); the bot\ncannot clear it, but you can, by removing the connection in Discord's settings (Connections).</p>\n<p><strong>Renames Blizzard required.</strong> When a roster export shows that a character bound to you was renamed (the\nsame character under a new name), the link follows the character and the site's administrators see the old and new\nname. If an administrator marks the rename as required by Blizzard, the bot records that decision (your Discord user\nID, both names, that character's key and in-game identifier, when it was decided, by whom, and when it was closed): the\ncharacter is unbound and has to be verified again, your site application is set back so that you submit it again, your\nGuild Member role is removed and held unless another of your characters is in the guild, and <code>/verify-status</code>\ntells you why; an administrator approves once your new application was accepted and the character verified again, or\nwithdraws the decision. The record is deleted thirty days after it was approved or withdrawn; while it is open it\nstays.</p>\n\n<h2>Where it goes</h2>\n<p>Data lives in a Cloudflare D1 database owned by the guild's officers, in Cloudflare's infrastructure, together with\nthe site's files and the Worker's logs (Workers Logs keep what the bot prints: fixed error categories and bounded status\ncodes, never messages, tokens, codes, tags or addresses). A working copy of the invite queue, the addon's saved data and\nthe game's chat log sit on the computer of the officer who sends the invites. The bot talks to Discord as part of its\nordinary work: it reads members' roles and nicknames, grants and removes the Guild Member role, sets nicknames where that\nis switched on, bans where an officer orders it, writes a short reason into Discord's own audit log for those changes,\nrefreshes the Discord usernames and display names of linked members, re-checks a signed-in member's server membership\nabout hourly after a save, and posts the notices and staff messages described below; Discord keeps its own records of all\nthat under its terms. While Battle.net sign-in is switched off, Blizzard receives nothing from this bot. Nothing is sold or used for\nadvertising, training or analytics, and there are no third-party trackers on this page; beyond what this page describes,\nnothing is shared.</p>\n\n<h2>Who can see it</h2>\n<p>Guild officers, through the bot's own commands and their in-game addon, can see which Discord account a character\nbelongs to, its Discord username and display name, and how its verification went. The same lookup tells them whether\nyou applied on the guild site, for which role and how far it got, and the character names you reserved. The site's\nadministrators can see everything you entered on the site. Other members can see that you have signed up there (when\nthey search for someone to write in or list as a friend), if you put a leadership application on the voting board, what\nthe board shows, and what you list for them on the community pages (your directory profile and crafting offers, your\ncalendar answers), as those sections say; nothing else you entered. Confirmed members can also read the News page while\nit is on: the figures the site works out by itself, which are counts and times and never your name or your place in the\ninvite queue; the next events with the titles their organizers gave them, as the calendar shows them; and the notices\nthe administrators write for the whole guild, which name a member only with that member's agreement (see News, above,\nto have one changed or deleted). If you hold an appointed role, anyone, signed in or not,\nsees your name as its holder, as said under the guild site. Beyond that, everyone else in the server sees only what the\nbot shows in public: your server nickname, where the staff\nhave switched that on, which it then sets to your character's name when you are admitted; and the short notices in the server's bot notices channel (#olympus-notices) that mention you\nwhen your access changes. The Terms of\nService list which notices those are; anything you might not want read out only says there is an update, and\n<code>/verify-status</code> shows the detail to you alone. The bot's log channel is private to staff.</p>\n<p>The site's administrators also use the staff pages of the community features: the directory's claims review,\ntrials, cases and their watch-lists, departure items, the dues ledger with the payer names and sources of recorded\npayments, the private request cases, the News notices with who posted and last changed each, and two staff views that\nchange nothing: a coverage report (the latest roster export\nnext to what the bot and the site already know about each bound account) and the counts behind the officer digest. Every\nchange a staff member makes is recorded in the dated log under their Discord user ID; reading is not. Once a day the bot\nmay post to a staff channel how many things wait for an officer, as counts only, never a name or an ID. A staff\nrank-planning page keeps its draft in that administrator's own browser and stores nothing on the server; that browser\ncopy outlives signing out and any deletion on the server until the administrator clears their browser's data.</p>\n\n<h2>Getting rid of it</h2>\n<p>Ask any Olympus officer (or, if you can no longer reach Discord, use the private request form described below). For the\nbot, an officer unbinds your characters: each character row is marked unbound and loses its in-game identifier, and your\nopen code requests and queue entries are cancelled; unbinding does not by itself remove your Guild Member role, which an\nofficer removes in Discord where it should go. The bot has no delete command: your member row\n(your Discord user ID and, if you were banned from verifying, the ban and its reason), the unbound character rows and the\ndated log stay, and the officers handle a request to erase the bot's data about you by hand, in the database, as a\nseparate request; unbinding alone is not erasure. Leaving the Discord server does none of this by itself. The guild's\nroster history is kept: it holds character names, ranks, notes and dates, and where the bot wrote your Discord user ID\ninto a character's public note the exported note carries it; the history is not scrubbed of it.</p>\n<p>The same goes for the guild site: ask any Olympus officer, and the site's administrators delete\neverything the site holds about you at once &mdash; your application, votes, write-ins, friends list and reserved names,\nthe votes others cast on your application, and your account there. On request they also remove what other members\nentered about you: write-ins naming you, friends-list entries, and references to you in their applications, with any\nnote written about you; this works even if you never signed in to the site. If your registration was permanently\ndenied, your account row is kept, emptied of your names, picture and account dates, with your Discord user ID, the\ndenial, its reason, when and by whom it was decided, and the row's operational state (whether you were in the server when\nlast checked and when that was, and the sign-in counter the site uses to end old sessions; the sign-in dates set to the\ndecision's moment), so the same account cannot simply sign up again.</p>\n<p><strong>Names the administrators typed.</strong> The holders of appointed roles and the names in the leadership\ndirectory are typed by the administrators and tied to no Discord account, so they are not in your copy and deleting your\nsite data does not find them. They are removed or corrected on request instead, as said under the leadership directory:\nask any Olympus officer, or use the private request form.</p>\n<p><strong>If you can no longer reach Discord</strong>, the site has a private request form\n(olympus.roachcouncil.com/#/request), when the staff have switched it on, that needs no sign-in: your browser makes a case number and a secret case code, you write what you ask\nfor (and, if you wish, a hint who you are or which character), and the administrators answer in that case. The case\nnumber is stored as it is: it names the case in the staff pages (their addresses included) and in the dated log, and the\nadministrators open a case by its number through their own signed-in staff session, without your code. The code is stored\nonly as a hash, so nobody can read it back; it travels only in your requests, never in a link, and it is what lets you,\nand only you, read and continue the case. The form keeps no email address and no\nIP address, and a case proves nothing about who owns an account: the administrators verify that in the conversation\nbefore acting through the site's own tools, and a case by itself exports, deletes or changes nothing. A case is kept for\nthe period the form states when you open it, counted from its last activity: a message from you, or a staff change while\nthe case is open, extends the deadline under that same period (reading never does), closing the case pins it, and a later\nchange to a closed case may update its activity time without extending it. Past the deadline the case is answered to no\none (judged by the database's own clock) and deleted in the scheduled cleanup, which works in bounded batches; nothing\nrecalls a copy you already took.</p>\n<p>The same deletion removes everything the community pages hold about you: your profile and offers, your event answers\nand attendance, your trials, your departure items, and your dues records (your weeks, the payments matched to you and your\nacknowledgements). What remains is this, and only this: the dated log of actions (each entry's name, who acted, whom or\nwhat it concerned and its recorded details, as described under what it stores, with your Discord user ID as the subject or\nas the actor); an active restriction case with its watch-list and the member period those rows\nrun under, because the case is about the account and not about the site (an inactive case is deleted with your account;\nthe period, whose dated renewal note the officers may read, survives only while one of your cases is still unresolved, and\nan ended period admits no new watch-list row and renews nothing); and the bot's own rows (your characters, your queue\nentries, your member row and any rename record), which the officers handle as described above (unbinding through the bot; erasure by hand on\nrequest). The\ndeparture review's cleanup keeps one shared bookmark of where its last scan of the guild's departures stopped (a departure\ntime and a character name key, never a Discord account ID); it is replaced on the next run and cleared when a run reaches\nthe end, and it is not about any one account. The officer digest keeps its own working state (the channel, the message it\nposted, a nonce, the day, a lease and the outcome), about no account. Private request cases are not account records at\nall: they are keyed by their number; you reach yours only with its code, the administrators reach them through their\nadmitted staff session; so deleting your site data does not touch them, and closing or deleting a case touches nothing\nelse. An administrator whose own account is erased is removed as the reviewer,\napprover, recorder, setter or author from every record the site keeps such a pointer in (a News notice they posted stays\nup for its period, without them as its author); the dated log keeps its actor IDs as said, Discord keeps its own\nmessages, and free text someone else wrote that happens to name them is not searched.</p>\n<p>Where a record has a stated lifetime &mdash; a trial, a case, a departure item, a dues record, a private request case,\na News notice &mdash; no page shows it and no new copy contains it from the moment the lifetime ends, judged by the\ndatabase's own clock inside each read, with the one exception stated above for the dues ledger (the minimum accounting of\nan expired payment, its kind, the amount it paid, the part retired, its date and status and which week, stays with a week\nthat is itself still within its period) and one for News: an administrator's own copy lists the notices they posted or\nlast changed, and the records left by their deleted ones, until the cleanup deletes them, each with the time its period\nends or ended; the physical deletion follows in the scheduled cleanup, which works in bounded batches, so it may take\nseveral runs, and waits while the Worker's schema check fails. Profiles and events follow their own rule, stated above,\nnot a deadline inside each read: a profile stops being shown as soon as its owner no longer qualifies and is deleted by\nthat cleanup thirty days later; an event, its answers and attendance remain as the calendar shows them until that cleanup\ndeletes them thirty days after it ended. None of this recalls a copy already downloaded, the officers' local working\ncopies, or what Discord holds in its own messages and logs.</p>\n<p><strong>Backups.</strong> Lifetimes and deletions apply to the live database at once. They do not reach two copies\nkept only to recover the database: the private export of the whole database that the owner takes before a deploy, and\nCloudflare's own point-in-time history of the database, which it keeps for up to 30 days. The owner keeps only the\nnewest export that has been checked by restoring it privately: an older one is destroyed once a newer one has been\nchecked, the last one is destroyed once the game's launch release is accepted, and after that each export is destroyed\nonce its own release is accepted. The export taken before build .115 therefore still holds the dated log as it was before the\nrewrite described under appointed roles, until it is destroyed. Neither copy is read in ordinary work; a deletion reaches\nthem when they are destroyed or age out. If one were ever restored, the site would be closed to everyone from just before\nthe restore until the owner has done the following on it: repeated the deletions made since it was taken; deleted every\nNews notice changed or deleted since then and put back the record of every notice posted since then, so that no notice\ncomes back in an earlier form (one changed since is deleted, and the administrators post it again if it is still wanted)\nand none can be posted again; and put back the names the administrators typed (the appointed roles and the leadership\ndirectory) exactly as they stood just before the restore, so that a name removed or corrected on request stays removed or\ncorrected. For the names the owner takes a private copy of just those two settings right before restoring and destroys\nit once they are back; the dated log never receives the names. The owner also checks the restored database for the\nrewrite described under appointed roles, as after installing build .115.</p>\n\n<h2>Your copy</h2>\n<p>While signed in to the site you can download a copy of what it and the bot hold about your Discord account, curated\nfor you (the site's address followed by <code>/api/me/export</code>). It lists your account; your application, with the people you\nnamed as references by the names you chose, not their accounts; your votes and friends by the labels you chose; your\nreserved names; the bot's view of you (whether you are banned from verifying, whether a Battle.net link is current\n&mdash; never the BattleTag &mdash;, the characters bound to you, your code requests without any code, your place in the\ninvite queue, and any rename record, without the administrators' identities); the dated actions that name your account, shown as their time and action name only (the earliest\nthousand, with a way to continue); and every community page's records about you, which for an administrator include the\nNews notices they posted or last changed (each notice's id, title and dates) and the ids and dates of the notices they\nposted that are gone. It leaves out staff notes and reasons, staff identities, the raw roster snapshots and the private\ndetails of recorded payments; names the administrators typed (appointed roles, the leadership directory) are tied to no\naccount and are not in it, as said under getting rid of it; your own labels and free text are\ncopied as you wrote them, so they can name other people. Each copy, and each continuation of the dated actions, is read in\none go at the moment it states, and the Worker allows about five copies an hour (a limit it keeps in memory, so\napproximate). A private request case is not in it: cases are keyed by their number, not by any account, and are read only\nwith their code.</p>\n\n<h2>Contact</h2>\n<p>Olympus's officers in Asmongold's Discord server, or the site's private request form if you can no longer reach Discord.\nThis bot is run by volunteers, not a company.</p>\n\n<p class=\"meta related\">See also the <a href=\"/terms\">Terms of Service</a>.</p>\n</main>\n</body>\n</html>\n";
const TERMS = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Olympus Verify — Terms of Service</title>\n<meta name=\"color-scheme\" content=\"dark\">\n<link rel=\"stylesheet\" href=\"/static/policies.css\">\n</head>\n<body class=\"olympus-policy\">\n<a class=\"skip-link\" href=\"#policy-content\">Skip to policy</a>\n<header class=\"policy-header\">\n<a class=\"brand\" href=\"/\">Olympus</a>\n<nav aria-label=\"Policies\"><a href=\"/privacy\">Privacy Policy</a><a href=\"/terms\" aria-current=\"page\">Terms of Service</a></nav>\n</header>\n<main id=\"policy-content\" tabindex=\"-1\">\n<h1>Terms of Service</h1>\n<p class=\"meta\">Olympus Verify and the Olympus guild site · last updated 3 October 2026</p>\n\n<p>Olympus Verify and the Olympus guild site are provided free, as-is, with no warranty, by the volunteer staff of one\nWorld of Warcraft guild, for the use of that guild's members and applicants. They are not a commercial service, and the\nbot is not available for installation elsewhere.</p>\n\n<h2>Using it</h2>\n<p>By verifying a character you confirm it is yours. Claiming someone else's character,\nsharing verification codes, or using the bot to gain access you were not given is grounds for losing guild and Discord\naccess.</p>\n\n<h2>The guild site</h2>\n<p>By applying you confirm that what you wrote is true and that the account is yours. Joke, troll and abusive\napplications are permanently denied, and so is voting under several accounts. A leadership application goes on the\nvoting board, where members can read it and vote on it, only when you tick the box that allows it; you can withdraw it\nat any time. Applying (first choice or backup), voting, writing someone in and entering a reserved name are requests\nand opinions, not promises: the guild's leadership decides roles and invitations.</p>\n<p><strong>The community pages.</strong> What you list in the directory or offer as crafting is yours to change or\nwithdraw at any time while the page is on; a calendar answer can be given or changed until the event starts; a character\nname you enter is a claim until it matches the officers' record.\nThe records the officers keep about you there &mdash; trials, restriction cases and their watch-lists, departure items,\nthe dues ledger &mdash; are the guild's staff records; they do not by themselves grant or remove access, roles or\nmembership. Guild dues are the guild's own arrangement: the ledger records what the officers confirm was paid, the mail\nreference is a matching aid and not proof of payment, and any question about a payment or a week is for the officers.\nThe site's administrators have a rank-planning page whose drafts stay in their own browser; a draft is a proposal, never a\nchange in the guild. The leadership directory of the Olympus guilds is a record the administrators keep; being listed\nthere gives no powers. News notices are the administrators' announcements to the guild, and the News figures are\napproximate counts; neither is a promise.</p>\n<p><strong>A full guild.</strong> While Olympus I is full, a character whose code was confirmed keeps its place in the\ninvite queue, and a refusal for lack of space costs it no invite attempt. A place in the queue is not a seat and promises\nno date, and names reserved on the site go first. The bot removes nobody to make room; officers may remove inactive\ncharacters.</p>\n<p><strong>Renamed characters.</strong> A character renamed because Blizzard required it, as a site administrator\ndecides, has to be verified again and its owner has to apply again; unless another of the owner's characters is in the\nguild, the Guild Member role is held until the leadership accepts the new application and the character is verified\nagain.</p>\n<p>The site is a free, non-commercial fan project. It is not affiliated with or endorsed by Blizzard Entertainment. It\nuses interface artwork and icons from the World of Warcraft game client, which remain the property of Blizzard\nEntertainment, Inc., and two interface fonts taken from the same client (Friz Quadrata, whose embedded notice names\nInternational Typeface Corporation, 1997, and Morpheus, whose embedded notice names Kiwi Media/Design, Eric Oehler, 1996),\nreproduced with those notices intact; nothing here claims their ownership or grants any right to redistribute them, and\nthe site's own code licence does not extend to them. World of Warcraft and Blizzard Entertainment are trademarks or\nregistered trademarks of Blizzard Entertainment, Inc.</p>\n\n<h2>How it tells you about your access</h2>\n<p>The bot never sends direct messages. When something changes about your own access &mdash; your character is on the\nguild roster, you are back in the invite queue, or a seat was freed &mdash; it posts a short notice in the server's bot\nnotices channel (#olympus-notices) and mentions you, so you get an ordinary notification. Only the welcome (your character is on the guild roster) is said in\nfull; every other notice, including being back in the queue or a freed seat, and anything you might not want read out in\nfront of the server, such as an invite that was declined or refused or an application that was decided, only says there\nis an update, and <code>/verify-status</code> shows you the detail privately. In that\nchannel it posts nothing else &mdash; no announcements, no marketing &mdash; and it is rate-limited; whether a notice\nreaches you depends on the channel's permissions and on Discord. The bot also writes to the staff's own channels: its log\nlines, review cards and, where the officers switch it on, a daily digest of how many things wait for them, as counts only.\nYou can mute the notices channel at any time; <code>/verify-status</code> always shows the same information on request.</p>\n\n<h2>Availability</h2>\n<p>Staff may change, pause or retire the bot at any time. Guild membership itself is decided by officers, not by this\nsoftware; the bot only reflects the in-game guild roster.</p>\n\n<p class=\"meta related\">See also the <a href=\"/privacy\">Privacy Policy</a>.</p>\n</main>\n</body>\n</html>\n";

/** .114: whether the privacy policy carries the marked Battle.net sign-in section (<!-- olympus:bnet-login-section -->); gates src/bnet-switch.ts. */
export const PRIVACY_DESCRIBES_BNET_LOGIN = false;

/** The canonical policy document a path names, or null. Aliases keep every address that ever served or redirected one. */
export function policyDocument(path: string): string | null {
  if (["/privacy", "/privacy-policy", "/privacy.html"].includes(path)) return PRIVACY;
  if (["/terms", "/tos", "/terms-of-service", "/terms.html"].includes(path)) return TERMS;
  return null;
}
